using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based resolution
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ there's a generic helper – but the cast-free approach is via the
// resolver. The simplest cast-free way today:
JsonTypeInfo<Person> typed = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> – Kind: {typed.Kind}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about Person to show the "not available" path.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};
// DefaultJsonTypeInfoResolver can resolve anything via reflection, so to demo
// a "not available" case we use a source-gen context that only has Person.
var strict = new JsonSerializerOptions
{
    TypeInfoResolver = PersonContext.Default
};

if (strict.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"Person metadata found – Kind: {info!.Kind}");
else
    Console.WriteLine("Person metadata NOT found");

if (strict.TryGetTypeInfo(typeof(Order), out JsonTypeInfo? orderInfo))
    Console.WriteLine($"Order metadata found – Kind: {orderInfo!.Kind}");
else
    Console.WriteLine("Order metadata NOT found (no exception thrown)");

// --- Types ---------------------------------------------------------------
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A source-generated context that only knows about Person
[JsonSerializable(typeof(Person))]
public partial class PersonContext : JsonSerializerContext;

